svg.script:

(function() {
  'use strict';

  // Dados determinísticos dos 5 marcos anatômicos
  var marcos = [
    {
      id: 0,
      title: "1. PROMONTÓRIO SACRAL (MARCO POSTERIOR INICIAL)",
      desc: "Projeção anterior da margem superior da 1ª vértebra sacral (S1). Âncora posterior da linha inominada.",
      relevancia: "Ponto fixo posterior para medida do Diâmetro Conjugado Obstétrico (mínimo normal ~10,5 cm).",
      regra: "Ponto divisor posterior: Estruturas acima pertencem à cavidade abdominal / pelve falsa.",
      sag: { x: 335, y: 105 },
      sup: { x: 202, y: 65 }
    },
    {
      id: 1,
      title: "2. LINHA ARQUEADA DO ÍLIO (SEGMENTO LATERAL)",
      desc: "Crista óssea curva e suave na superfície medial do ílio, estendendo-se inferior e anterior ao sacro.",
      relevancia: "Constitui a parede lateral do estreito superior pélvico. Guia a passagem da apresentação fetal.",
      regra: "Separa a fossa ilíaca (pelve maior, superior) da parede pélvica lateral (pelve menor, inferior).",
      sag: { x: 278.7, y: 143.7 },
      sup: { x: 270, y: 115 }
    },
    {
      id: 2,
      title: "3. EMINÊNCIA ILIOPÚBICA (PONTO DE INFLEXÃO ANTEROLATERAL)",
      desc: "Elevação óssea localizada na zona de fusão entre o ílio e o púbis, correspondendo à margem acetabular.",
      relevancia: "Marca a inflexão de curvatura do anel pélvico no estreito superior.",
      regra: "Ponto de ancoragem anterior médio no plano do estreito superior pélvico.",
      sag: { x: 222.5, y: 182.5 },
      sup: { x: 268, y: 178 }
    },
    {
      id: 3,
      title: "4. LINHA PECTÍNEA / PÉCTEN DO PÚBIS (SEGMENTO ANTERIOR)",
      desc: "Crista afiada na margem superior do ramo superior do osso púbico.",
      relevancia: "Inserção do ligamento pectíneo (Cooper) e marco anatômico para herniorrafias pélvicas.",
      regra: "Continuação anterior imediata da linha arqueada até a sínfise púbica.",
      sag: { x: 166.2, y: 221.2 },
      sup: { x: 232, y: 235 }
    },
    {
      id: 4,
      title: "5. BORDA SUPERIOR DA SÍNFISE PÚBICA (MARCO ANTERIOR FINAL)",
      desc: "Margem superior da articulação fibrocartilaginosa pubiana na linha média anterior.",
      relevancia: "Encerra o contorno da linha terminal. Limite anterior do diâmetro conjugado verdadeiro (11,0 cm).",
      regra: "Ponto divisor anterior: Abaixo deste marco inicia-se diretamente o Canal de Parto.",
      sag: { x: 110, y: 260 },
      sup: { x: 202, y: 263 }
    }
  ];

  var currentIdx = 0;

  function updateScene(idx) {
    if (idx < 0 || idx >= marcos.length) return;
    currentIdx = idx;
    var data = marcos[idx];

    // 1. Atualizar posição dos cursores nos dois painéis
    var curSag = document.getElementById('a12p8-cursor-sagittal-group');
    var curSup = document.getElementById('a12p8-cursor-superior-group');
    if (curSag) curSag.setAttribute('transform', 'translate(' + data.sag.x + ', ' + data.sag.y + ')');
    if (curSup) curSup.setAttribute('transform', 'translate(' + data.sup.x + ', ' + data.sup.y + ')');

    // 2. Atualizar feixe de sincronização entre painéis
    var syncBeam = document.getElementById('a12p8-sync-beam-line');
    if (syncBeam) {
      // Coordenadas absolutas adicionando o offset do painel sagital (20) e superior (435)
      syncBeam.setAttribute('x1', data.sag.x + 20);
      syncBeam.setAttribute('y1', data.sag.y + 75);
      syncBeam.setAttribute('x2', data.sup.x + 435);
      syncBeam.setAttribute('y2', data.sup.y + 75);
    }

    // 3. Atualizar estados ativos nos botões de passo
    for (var i = 0; i < 5; i++) {
      var btn = document.getElementById('a12p8-btn-step-' + i);
      var sagPt = document.getElementById('a12p8-sag-pt-' + i);
      var supPt = document.getElementById('a12p8-sup-pt-' + i);

      if (btn) {
        if (i === idx) {
          btn.classList.add('a12p8-active');
          btn.setAttribute('aria-selected', 'true');
        } else {
          btn.classList.remove('a12p8-active');
          btn.setAttribute('aria-selected', 'false');
        }
      }

      if (sagPt) {
        if (i === idx) sagPt.classList.add('a12p8-active');
        else sagPt.classList.remove('a12p8-active');
      }

      if (supPt) {
        if (i === idx) supPt.classList.add('a12p8-active');
        else supPt.classList.remove('a12p8-active');
      }
    }

    // 4. Atualizar os textos do painel de leitura
    var titleEl = document.getElementById('a12p8-card-title');
    var descEl = document.getElementById('a12p8-card-desc');
    var relEl = document.getElementById('a12p8-card-relevancia');
    var regEl = document.getElementById('a12p8-card-regra');
    var tagEl = document.getElementById('a12p8-card-tag');

    if (titleEl) titleEl.textContent = data.title;
    if (descEl) descEl.textContent = data.desc;
    if (relEl) relEl.textContent = data.relevancia;
    if (regEl) regEl.textContent = data.regra;
    if (tagEl) tagEl.textContent = 'MARCO ' + (idx + 1) + ' DE 5 · PERCURSO ANATÔMICO VERBATIM';
  }

  // Handler para clique e teclado
  function setupListeners() {
    for (var i = 0; i < 5; i++) {
      (function(index) {
        var btn = document.getElementById('a12p8-btn-step-' + index);
        var sagPt = document.getElementById('a12p8-sag-pt-' + index);
        var supPt = document.getElementById('a12p8-sup-pt-' + index);

        var handler = function(e) {
          if (e.type === 'keydown' && e.key !== 'Enter' && e.key !== ' ') return;
          e.preventDefault();
          updateScene(index);
        };

        if (btn) {
          btn.addEventListener('click', handler);
          btn.addEventListener('keydown', handler);
        }
        if (sagPt) {
          sagPt.addEventListener('click', handler);
          sagPt.addEventListener('keydown', handler);
        }
        if (supPt) {
          supPt.addEventListener('click', handler);
          supPt.addEventListener('keydown', handler);
        }
      })(i);
    }

    // Navegação global por setas do teclado (Esquerda/Direita)
    document.addEventListener('keydown', function(e) {
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        var next = (currentIdx + 1) % 5;
        updateScene(next);
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        var prev = (currentIdx - 1 + 5) % 5;
        updateScene(prev);
      }
    });
  }

  // Inicialização
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setupListeners();
      updateScene(0);
    });
  } else {
    setupListeners();
    updateScene(0);
  }
})();
